        # its BLK-wide panel at column offset j (height pheight). Smem holds each
        # CTA's row-slice (sliceH x BLK) + per-warp reduction scratch.
        import numpy as np
        cd = self.cd
        per = (pheight + G - 1) // G
        sliceH = min(per, pheight)            # max slice (CTA 0); smem sized to it
        nwarps = (nthreads + 31) // 32
