_KERNEL = None


def _get_kernel():
    global _KERNEL
    if _KERNEL is None:
        _KERNEL = _SmallQRKernel()
    return _KERNEL


def _small_qr(A):
    B, n, _ = A.shape
    kern = _get_kernel()
    # smem budget (floats): n*n + 32 (warp scratch) + n (v)
