// ===========================================================================
// brief-56 CUDA MEGAKERNEL (user-directed: "Write a CUDA C++ megakernel ...
// I don't care if it's a huge error prone task do it"). Fuses the n512 panel-
// factor + WY trailing-apply into ONE launch, one CTA per matrix. Both the
// reflector panel V/R (sP) AND the current trailing column strip (sA) live in
// SMEM, resident across the factor->apply boundary AND across the two WY sweeps,
// so (a) the panel never spills to local memory (W3's +2.2x root cause on the
// Triton mega: the 64KB register panel spilled 1.32MB to local), (b) the Vbuf/
// Tbuf HBM round-trip is gone (V is the in-smem panel; T in smem), and (c) the
// A column strip is read from HBM ONCE (resident across both sweeps) instead of
// twice -- the L1-streaming re-read W3 measured as the trailing's sole remaining
// lever. Trailing GEMMs run on TENSOR CORES (WMMA m16n16k8 tf32x3, the 3-MMA
// error-corrected split a_hi*b_hi+a_hi*b_lo+a_lo*b_hi recovering ~fp32). B200
// optin smem is 227KB so a 64KB panel + a 32-col A strip + W/T scratch fits at
// 1-2 blocks/SM (NOT the 8.6x 1-block/whole-matrix collapse: only the WORKING
// SET is resident, the matrix stays in HBM, and the grid is B=640 CTAs over 148
// SMs so the GPU is filled at matrix granularity).
//
// Householder convention bit-identical to torch.geqrf / LAPACK dlarfg, matched to
// _panel_factor2_kernel. Per matrix, right-looking blocked over outer blocks of
// width BLK (NB=32): factor the BLK-wide panel (cols [j,j+BLK), rows [j,N)) into
// sP, build the BLKxBLK compact-WY T into sT, then apply A[:, j+BLK:N] -= V T^T
// V^T A in BNc-column strips with V/T resident.
// ---------------------------------------------------------------------------
typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> MFragAR;
typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::col_major> MFragAC;
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::col_major> MFragBC;
typedef wmma::fragment<wmma::accumulator, 16, 16, 8, float> MFragAcc;

extern "C" __global__ void qr_mega_n512(
    const float* __restrict__ Ain,   // (B, N, N) row-major source
    float* __restrict__ Hout,        // (B, N, N) row-major dest (factored in place after block 0)
    float* __restrict__ tauout,      // (B, N)
    int B, int N,
    int strideAb, int strideAn,      // A/H strides (elements): batch, row
    int BLK, int BNc, int PHpad0)    // BLK=32 panel width; BNc trailing strip; PHpad0 = ceil(N/16)*16
{
    const int bid = blockIdx.x;
    if (bid >= B) return;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int WB = nthr >> 5;

    extern __shared__ float smem_mg[];
    // sP: panel (PHpad0 x BLK) col-major, ldm PHpad0 (resident V below diag + R diag).
    float* sP   = smem_mg;
    // sA: trailing strip (PHpad0 x BNc) col-major, ldm PHpad0 (resident across both sweeps).
    float* sA   = sP + (long)PHpad0 * BLK;
    // sW / sWpp: (BLK x BNc) col-major, ldm BLK.
    float* sW   = sA + (long)PHpad0 * BNc;
    float* sWpp = sW + (long)BLK * BNc;
    // sT: (BLK x BLK) col-major, ldm BLK (the compact-WY T).
    float* sT   = sWpp + (long)BLK * BNc;
    // sred: per-warp reduction scratch (max(WB, BLK) floats) + a few broadcast slots.
    float* sred = sT + (long)BLK * BLK;       // WB floats
    float* sbc  = sred + (WB > BLK ? WB : BLK); // small broadcast: [0]=tail2,[1]=alpha

    const float* Ab = Ain + (long)bid * strideAb;
    float* Hb = Hout + (long)bid * strideAb;
    float* taub = tauout + (long)bid * N;

    const int nblocks = N / BLK;              // N multiple of BLK (512/32=16)
    for (int jb_i = 0; jb_i < nblocks; ++jb_i) {
        const int j = jb_i * BLK;
        const int pheight = N - j;
        const int PHpad = ((pheight + 15) / 16) * 16;  // rounded up for WMMA frags
        // block 0 reads A (clone fusion); later blocks read H (prior block's trailing).
        const float* src = (jb_i == 0) ? Ab : Hb;

        // ---- load panel cols [j, j+BLK) rows [j, N) into sP (col-major), pad to 0 ----
        for (long idx = tid; idx < (long)PHpad * BLK; idx += nthr) {
            int r = idx % PHpad;       // panel-local row 0..PHpad-1
            int c = idx / PHpad;       // panel col 0..BLK-1
            float v = 0.0f;
            if (r < pheight) v = src[(long)(j + r) * strideAn + (j + c)];
            sP[idx] = v;
        }
        // zero sT
        for (int idx = tid; idx < BLK * BLK; idx += nthr) sT[idx] = 0.0f;
        __syncthreads();

        // ---- factor the BLK-wide panel in smem (NB Householder reflectors) ----
        // sP[c*PHpad + r] = panel(row r, col c). Convention == _panel_factor2_kernel.
        for (int k = 0; k < BLK; ++k) {
            float* colk = sP + (long)k * PHpad;
            // tail2 = sum_{r>k, r<pheight} colk[r]^2 (cross-warp reduction)
            float part = 0.0f;
            for (int r = k + 1 + tid; r < pheight; r += nthr) {
                float x = colk[r]; part += x * x;
            }
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                part += __shfl_down_sync(0xffffffffu, part, off);
            if (lane == 0) sred[warp] = part;
            __syncthreads();
            if (tid == 0) {
                float s = 0.0f;
                for (int w2 = 0; w2 < WB; ++w2) s += sred[w2];
                sbc[0] = s;
                sbc[1] = colk[k];            // alpha
            }
            __syncthreads();
            float tail2 = sbc[0];
            float alpha = sbc[1];

            float beta, tau_k, scale;
            if (tail2 == 0.0f) { beta = alpha; tau_k = 0.0f; scale = 1.0f; }
            else {
                float normx = sqrtf(alpha * alpha + tail2);
                float sgn = (alpha >= 0.0f) ? 1.0f : -1.0f;
                beta = -sgn * normx;
                tau_k = (beta - alpha) / beta;
                scale = 1.0f / (alpha - beta);
            }
            // write v into colk: v[k]=1, v[r>k]=colk[r]*scale (rows<k untouched=0-ish but unused)
            for (int r = k + 1 + tid; r < pheight; r += nthr) colk[r] *= scale;
            __syncthreads();
            if (tid == 0) colk[k] = 1.0f;     // v[k]=1 (temp; finalized to beta below)
            __syncthreads();

            if (tau_k != 0.0f) {
                // w[c] = sum_{r>=k, r<pheight} v[r] * panel[r,c], for c in (k, BLK)
                for (int c = k + 1 + warp; c < BLK; c += WB) {
                    float* colc = sP + (long)c * PHpad;
                    float acc = 0.0f;
                    for (int r = k + lane; r < pheight; r += 32)
                        acc += colk[r] * colc[r];
                    #pragma unroll
                    for (int off = 16; off > 0; off >>= 1)
                        acc += __shfl_down_sync(0xffffffffu, acc, off);
                    if (lane == 0) sW[c] = tau_k * acc;   // park tau*w[c] in sW row buffer
                }
                __syncthreads();
                // apply to trailing panel cols c>k: panel[r,c] -= v[r] * (tau*w[c])
                for (int c = k + 1; c < BLK; ++c) {
                    float twc = sW[c];
                    float* colc = sP + (long)c * PHpad;
                    for (int r = k + tid; r < pheight; r += nthr)
                        colc[r] -= colk[r] * twc;
                }
                // T column k: T[a<k,k] = -tau_k * sum_{c<k} T[a,c] * w[c]; w[c]=sW2[c].
                // We need w[c<k] = V[:,c].v_k. Recompute (cheap, c<k <= 31).
                __syncthreads();
                for (int c = warp; c < k; c += WB) {
                    float* colc = sP + (long)c * PHpad;
                    float acc = 0.0f;
                    for (int r = k + lane; r < pheight; r += 32)
                        acc += colk[r] * colc[r];     // v_k . V[:,c] (c<k)
                    #pragma unroll
                    for (int off = 16; off > 0; off >>= 1)
                        acc += __shfl_down_sync(0xffffffffu, acc, off);
                    if (lane == 0) sWpp[c] = acc;     // w[c<k]
                }
                __syncthreads();
                if (warp == 0) {
                    for (int a = lane; a < BLK; a += 32) {
                        if (a < k) {
                            float s = 0.0f;
                            for (int c = 0; c < k; ++c)
                                s += sT[(long)k * BLK + a] * 0.0f;  // placeholder (overwritten below)
                            // T[a,k] = -tau_k * sum_{c<k} T[a,c]*w[c]
                            float acc = 0.0f;
                            for (int c = 0; c < k; ++c)
                                acc += sT[(long)c * BLK + a] * sWpp[c];
                            sT[(long)k * BLK + a] = -tau_k * acc;
                        } else if (a == k) {
                            sT[(long)k * BLK + a] = tau_k;
                        }
                    }
                }
                __syncthreads();
            } else {
                if (warp == 0 && lane == 0) sT[(long)k * BLK + k] = 0.0f;
                __syncthreads();
            }
            // finalize column k diagonal: beta (or alpha if no reflector). tau.
            if (tid == 0) {
                colk[k] = (tail2 == 0.0f) ? alpha : beta;
                taub[j + k] = tau_k;
            }
            __syncthreads();
        }

        // ---- write panel (V below diag + R on/above diag) back to H ----
        for (long idx = tid; idx < (long)pheight * BLK; idx += nthr) {
            int r = idx % pheight;
            int c = idx / pheight;
            Hb[(long)(j + r) * strideAn + (j + c)] = sP[(long)c * PHpad + r];
        }
        __syncthreads();

        // ---- fused trailing: A[:, j+BLK:N] -= V @ (T^T @ (V^T @ A_strip)) ----
        const int ncols = N - (j + BLK);
        const int jt = j + BLK;
        for (int c0 = 0; c0 < ncols; c0 += BNc) {
            // load A strip cols [jt+c0, jt+c0+BNc) into sA (col-major, padded 0).
            for (long idx = tid; idx < (long)PHpad * BNc; idx += nthr) {
                int r = idx % PHpad;
                int c = idx / PHpad;
                int gc = c0 + c;             // trailing-relative col
                float v = 0.0f;
                if (r < pheight && gc < ncols) v = src[(long)(j + r) * strideAn + (jt + gc)];
                sA[idx] = v;
            }
            __syncthreads();

            // Step 1: W[BLK x BNc] = V^T @ sA   (M=BLK, N=BNc, K=PHpad). V = sP cols
            // as reflectors: V[r,k]=sP[k*PHpad+r] (1 on diag, refl below, 0 above --
            // sP holds exactly that after the factor, since rows<k of colk are 0).
            // A frag = V^T[k,r] row-major: ldm between rows(k) = PHpad (sP col stride),
            //   within row(r) step 1. So frag base sP + mi*16*PHpad (rows=k) won't work
            //   directly -- V^T[k,r] = sP[k*PHpad + r]; as a row-major (k,r) matrix the
            //   row index k strides by PHpad and col index r strides by 1 -> ldm=PHpad.
            {
                int mt = BLK / 16, nt = BNc / 16, kt = PHpad / 8;
                for (int tile = warp; tile < mt * nt; tile += WB) {
                    int mi = tile / nt, ni = tile % nt;
                    MFragAcc acc; wmma::fill_fragment(acc, 0.0f);
                    for (int kk = 0; kk < kt; ++kk) {
                        // V^T rows [mi*16,+16)=k, cols [kk*8,+8)=r -> sP + mi*16*PHpad + kk*8
                        MFragAR a; wmma::load_matrix_sync(a, sP + (long)mi * 16 * PHpad + (long)kk * 8, PHpad);
                        // sA rows [kk*8,+8)=r, cols [ni*16,+16) -> sA + kk*8 + ni*16*PHpad (col-major ldm PHpad)
                        MFragBC b; wmma::load_matrix_sync(b, sA + (long)kk * 8 + (long)ni * 16 * PHpad, PHpad);
                        MFragAR ah, al; MFragBC bh, bl;
                        #pragma unroll
                        for (int e = 0; e < a.num_elements; ++e) { float hv = wmma::__float_to_tf32(a.x[e]); ah.x[e]=hv; al.x[e]=wmma::__float_to_tf32(a.x[e]-hv); }
                        #pragma unroll
                        for (int e = 0; e < b.num_elements; ++e) { float hv = wmma::__float_to_tf32(b.x[e]); bh.x[e]=hv; bl.x[e]=wmma::__float_to_tf32(b.x[e]-hv); }
                        wmma::mma_sync(acc, ah, bh, acc);
                        wmma::mma_sync(acc, ah, bl, acc);
                        wmma::mma_sync(acc, al, bh, acc);
                    }
                    wmma::store_matrix_sync(sW + (long)mi * 16 + (long)ni * 16 * BLK, acc, BLK, wmma::mem_col_major);
                }
            }
            __syncthreads();
            // Step 2: Wpp[i,g] = -sum_{l<=i} T[l,i] W[l,g]  (T col-major sT[i*BLK+l]).
            for (int idx = tid; idx < BLK * BNc; idx += nthr) {
                int g = idx / BLK, i = idx % BLK;
                float a = 0.f;
                for (int l = 0; l <= i; ++l)
                    a += sT[(long)i * BLK + l] * sW[(long)l + (long)g * BLK];
                sWpp[(long)i + (long)g * BLK] = -a;
            }
            __syncthreads();
            // Step 3: sA += V @ Wpp  (== sA - V @ T^T V^T A). A=V col-major (PHpad x BLK):
            // V[r,k]=sP[k*PHpad+r] -> col-major frag ldm between cols(k)=PHpad, within col(r)=1.
            {
                int mt = PHpad / 16, nt = BNc / 16, kt = BLK / 8;
                for (int tile = warp; tile < mt * nt; tile += WB) {
                    int mi = tile / nt, ni = tile % nt;
                    MFragAcc acc;
                    wmma::load_matrix_sync(acc, sA + (long)mi * 16 + (long)ni * 16 * PHpad, PHpad, wmma::mem_col_major);
                    for (int kk = 0; kk < kt; ++kk) {
                        int kb = kk * 8;
                        // V col-major: rows [mi*16,+16)=r, cols [kb,+8)=k -> sP + mi*16 + kb*PHpad
                        MFragAC a; wmma::load_matrix_sync(a, sP + (long)mi * 16 + (long)kb * PHpad, PHpad);
                        MFragBC b; wmma::load_matrix_sync(b, sWpp + kb + (long)ni * 16 * BLK, BLK);
                        MFragAC ah, al; MFragBC bh, bl;
                        #pragma unroll
                        for (int e = 0; e < a.num_elements; ++e) { float hv = wmma::__float_to_tf32(a.x[e]); ah.x[e]=hv; al.x[e]=wmma::__float_to_tf32(a.x[e]-hv); }
                        #pragma unroll
                        for (int e = 0; e < b.num_elements; ++e) { float hv = wmma::__float_to_tf32(b.x[e]); bh.x[e]=hv; bl.x[e]=wmma::__float_to_tf32(b.x[e]-hv); }
                        wmma::mma_sync(acc, ah, bh, acc);
                        wmma::mma_sync(acc, ah, bl, acc);
                        wmma::mma_sync(acc, al, bh, acc);
                    }
                    wmma::store_matrix_sync(sA + (long)mi * 16 + (long)ni * 16 * PHpad, acc, PHpad, wmma::mem_col_major);
                }
            }
            __syncthreads();
            // write the updated strip back to H (valid rows/cols only).
            for (long idx = tid; idx < (long)pheight * BNc; idx += nthr) {
                int r = idx % pheight;
                int c = idx / pheight;
                int gc = c0 + c;
                if (gc < ncols) Hb[(long)(j + r) * strideAn + (jt + gc)] = sA[(long)c * PHpad + r];
            }
            __syncthreads();
        }
    }
}
