// ---- CONVERT sP in-place to the reflector matrix V (unit lower-trapezoidal):
// V[r,c] = 1 if r==c, sP[r,c] if r>c, 0 if r<c. sP currently holds R above
// the diagonal (and beta on it) -- the WMMA trailing reads sP AS V, so the
// above-diagonal R (and the beta diagonal) MUST be replaced by 0 / 1. sP was
// already written to H, so clobbering it here is safe. Also zero the padded
// rows r in [pheight, PHpad) so the WMMA K-padding contributes 0.
for (long idx = tid; idx < (long)PHpad * BLK; idx += nthr) {
    int r = idx % PHpad;
    int c = idx / PHpad;
    if (r >= pheight) sP[idx] = 0.0f;
    else if (r < c)   sP[idx] = 0.0f;
    else if (r == c)  sP[idx] = 1.0f;
    // r > c (and r < pheight): keep the reflector value already in sP.
}
