// fp16 fragments (k=16 tiles). Accumulate in fp32. half = __half.
typedef wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> HFragAR;
typedef wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::col_major> HFragAC;
