//       2 = fp16x2 (Ah*Bh + Ah*Bl, ~20-bit mantissa), 3 = fp16x3 (Ah*Bh+Ah*Bl+Al*Bh,
//       ~30-bit mantissa, matches tf32x3i; on B200 fp16 MMA ~2x tf32 throughput).
// Mirrors the Triton _dot_* helpers' precision ladder exactly.

// GEMM1: W[BLK x BNc] (col-major ldm BLK) = V^T @ sA.  V^T[k,r] = sP[k*PHpad+r]
// (row_major (k,r): ldm=PHpad). sA[r,c] col-major ldm PHpad. K = PHpad rows.
template<int PREC>
__device__ __forceinline__ void mega_gemm1(
    const float* sP, const float* sA, float* sW,
    int BLK, int BNc, int PHpad, int warp, int WB)
{
    int nt = BNc / 16;
    if (PREC == 0) {
        int mt = BLK / 16, kt = PHpad / 8;
        for (int tile = warp; tile < mt * nt; tile += WB) {
            int mi = tile / nt, ni = tile % nt;
            MFragAcc acc; wmma::fill_fragment(acc, 0.0f);
            for (int kk = 0; kk < kt; ++kk) {
                MFragAR a; wmma::load_matrix_sync(a, sP + (long)mi * 16 * PHpad + (long)kk * 8, PHpad);
                MFragBC b; wmma::load_matrix_sync(b, sA + (long)kk * 8 + (long)ni * 16 * PHpad, PHpad);
                MFragAR ah, al; MFragBC bh, bl;
                #pragma unroll
                for (int e = 0; e < a.num_elements; ++e) { float hv = wmma::__float_to_tf32(a.x[e]); ah.x[e]=hv; al.x[e]=wmma::__float_to_tf32(a.x[e]-hv); }
                #pragma unroll
                for (int e = 0; e < b.num_elements; ++e) { float hv = wmma::__float_to_tf32(b.x[e]); bh.x[e]=hv; bl.x[e]=wmma::__float_to_tf32(b.x[e]-hv); }
                wmma::mma_sync(acc, ah, bh, acc);
                wmma::mma_sync(acc, ah, bl, acc);
                wmma::mma_sync(acc, al, bh, acc);
            }
            wmma::store_matrix_sync(sW + (long)mi * 16 + (long)ni * 16 * BLK, acc, BLK, wmma::mem_col_major);
        }
    } else {
        int mt = BLK / 16, kt = PHpad / 16;
        for (int tile = warp; tile < mt * nt; tile += WB) {
            int mi = tile / nt, ni = tile % nt;
            HFragAcc acc; wmma::fill_fragment(acc, 0.0f);
            for (int kk = 0; kk < kt; ++kk) {
                HFragAR a; HFragBC b;
                // load fp32 -> a tmp then cast: WMMA load needs a half src, so load
                // via float frags is not possible; instead read the smem floats
                // through a half view by casting per-element after a float load.
                // Simplest: load into float frags then cast. But frag types differ.
                // Use load_matrix_sync on a half staging is overkill; instead build
                // half hi/lo by reading the float frag elementwise. WMMA has no float
                // load into a half frag, so we load the floats into a tf32-shaped
                // frag? No -- read raw: use a manual elementwise fill via the frag's
                // mapping is not exposed. So we cast in smem-free way: load a TF32
                // frag (same 16x16x8 shape won't match k=16). => stage halves in regs.
                // Practical path: load FLOAT frag (row/col major, generic) not avail.
                // Therefore we precast sP/sA to half in smem (done by caller for fp16).
                wmma::load_matrix_sync(a, ((const __half*)sP) + (long)mi * 16 * PHpad + (long)kk * 16, PHpad);
                wmma::load_matrix_sync(b, ((const __half*)sA) + (long)kk * 16 + (long)ni * 16 * PHpad, PHpad);
                wmma::mma_sync(acc, a, b, acc);
            }
            wmma::store_matrix_sync(sW + (long)mi * 16 + (long)ni * 16 * BLK, acc, BLK, wmma::mem_col_major);
        }
    }
}

