585	extern "C" __global__ void qr_mega_n512(
586	    const float* __restrict__ Ain,   // (B, N, N) row-major source
587	    float* __restrict__ Hout,        // (B, N, N) row-major dest (factored in place after block 0)
588	    float* __restrict__ tauout,      // (B, N)
589	    int B, int N,
590	    int strideAb, int strideAn,      // A/H strides (elements): batch, row
591	    int BLK, int BNc, int PHpad0)    // BLK=32 panel width; BNc trailing strip; PHpad0 = ceil(N/16)*16
592	{
593	    const int bid = blockIdx.x;
594	    if (bid >= B) return;
595	    const int tid = threadIdx.x;
596	    const int nthr = blockDim.x;
597	    const int lane = tid & 31;
598	    const int warp = tid >> 5;
599	    const int WB = nthr >> 5;
600	
601	    extern __shared__ float smem_mg[];
602	    // sP: panel (PHpad0 x BLK) col-major, ldm PHpad0 (resident V below diag + R diag).
603	    float* sP   = smem_mg;
604	    // sA: trailing strip (PHpad0 x BNc) col-major, ldm PHpad0 (resident across both sweeps).
605	    float* sA   = sP + (long)PHpad0 * BLK;
606	    // sW / sWpp: (BLK x BNc) col-major, ldm BLK.
607	    float* sW   = sA + (long)PHpad0 * BNc;
608	    float* sWpp = sW + (long)BLK * BNc;
609	    // sT: (BLK x BLK) col-major, ldm BLK (the compact-WY T).
610	    float* sT   = sWpp + (long)BLK * BNc;
611	    // sred: per-warp reduction scratch (max(WB, BLK) floats) + a few broadcast slots.
612	    float* sred = sT + (long)BLK * BLK;       // WB floats
613	    float* sbc  = sred + (WB > BLK ? WB : BLK); // small broadcast: [0]=tail2,[1]=alpha
614	
615	    const float* Ab = Ain + (long)bid * strideAb;
616	    float* Hb = Hout + (long)bid * strideAb;
617	    float* taub = tauout + (long)bid * N;
618	
619	    const int nblocks = N / BLK;              // N multiple of BLK (512/32=16)
620	    for (int jb_i = 0; jb_i < nblocks; ++jb_i) {
621	        const int j = jb_i * BLK;
622	        const int pheight = N - j;
623	        const int PHpad = ((pheight + 15) / 16) * 16;  // rounded up for WMMA frags
624	        // block 0 reads A (clone fusion); later blocks read H (prior block's trailing).
625	        const float* src = (jb_i == 0) ? Ab : Hb;
626	
627	        // ---- load panel cols [j, j+BLK) rows [j, N) into sP (col-major), pad to 0 ----
628	        for (long idx = tid; idx < (long)PHpad * BLK; idx += nthr) {
629	            int r = idx % PHpad;       // panel-local row 0..PHpad-1
630	            int c = idx / PHpad;       // panel col 0..BLK-1
631	            float v = 0.0f;
632	            if (r < pheight) v = src[(long)(j + r) * strideAn + (j + c)];
633	            sP[idx] = v;
634	        }
635	        // zero sT
636	        for (int idx = tid; idx < BLK * BLK; idx += nthr) sT[idx] = 0.0f;
637	        __syncthreads();
638	
639	        // ---- factor the BLK-wide panel in smem (NB Householder reflectors) ----
640	        // sP[c*PHpad + r] = panel(row r, col c). Convention == _panel_factor2_kernel.
641	        for (int k = 0; k < BLK; ++k) {
642	            float* colk = sP + (long)k * PHpad;
643	            // tail2 = sum_{r>k, r<pheight} colk[r]^2 (cross-warp reduction)
644	            float part = 0.0f;
645	            for (int r = k + 1 + tid; r < pheight; r += nthr) {
646	                float x = colk[r]; part += x * x;
647	            }
648	            #pragma unroll
649	            for (int off = 16; off > 0; off >>= 1)
650	                part += __shfl_down_sync(0xffffffffu, part, off);
651	            if (lane == 0) sred[warp] = part;
652	            __syncthreads();
653	            if (tid == 0) {
654	                float s = 0.0f;
655	                for (int w2 = 0; w2 < WB; ++w2) s += sred[w2];
656	                sbc[0] = s;
657	                sbc[1] = colk[k];            // alpha
658	            }
659	            __syncthreads();
660	            float tail2 = sbc[0];
661	            float alpha = sbc[1];
662	
663	            float beta, tau_k, scale;
664	            if (tail2 == 0.0f) { beta = alpha; tau_k = 0.0f; scale = 1.0f; }
665	            else {
666	                float normx = sqrtf(alpha * alpha + tail2);
667	                float sgn = (alpha >= 0.0f) ? 1.0f : -1.0f;
668	                beta = -sgn * normx;
669	                tau_k = (beta - alpha) / beta;
670	                scale = 1.0f / (alpha - beta);
671	            }
672	            // write v into colk: v[k]=1, v[r>k]=colk[r]*scale (rows<k untouched=0-ish but unused)
673	            for (int r = k + 1 + tid; r < pheight; r += nthr) colk[r] *= scale;
674	            __syncthreads();
675	            if (tid == 0) colk[k] = 1.0f;     // v[k]=1 (temp; finalized to beta below)
676	            __syncthreads();
677	
678	            if (tau_k != 0.0f) {
679	                // w[c] = sum_{r>=k, r<pheight} v[r] * panel[r,c], for c in (k, BLK)
680	                for (int c = k + 1 + warp; c < BLK; c += WB) {
681	                    float* colc = sP + (long)c * PHpad;
682	                    float acc = 0.0f;
683	                    for (int r = k + lane; r < pheight; r += 32)
684	                        acc += colk[r] * colc[r];
685	                    #pragma unroll
686	                    for (int off = 16; off > 0; off >>= 1)
687	                        acc += __shfl_down_sync(0xffffffffu, acc, off);
688	                    if (lane == 0) sW[c] = tau_k * acc;   // park tau*w[c] in sW row buffer
689	                }
690	                __syncthreads();
691	                // apply to trailing panel cols c>k: panel[r,c] -= v[r] * (tau*w[c])
692	                for (int c = k + 1; c < BLK; ++c) {
693	                    float twc = sW[c];
694	                    float* colc = sP + (long)c * PHpad;
695	                    for (int r = k + tid; r < pheight; r += nthr)
696	                        colc[r] -= colk[r] * twc;
697	                }
698	                // T column k: T[a<k,k] = -tau_k * sum_{c<k} T[a,c] * w[c]; w[c]=sW2[c].
699	                // We need w[c<k] = V[:,c].v_k. Recompute (cheap, c<k <= 31).
700	                __syncthreads();
701	                for (int c = warp; c < k; c += WB) {
702	                    float* colc = sP + (long)c * PHpad;
703	                    float acc = 0.0f;
704	                    for (int r = k + lane; r < pheight; r += 32)
705	                        acc += colk[r] * colc[r];     // v_k . V[:,c] (c<k)
706	                    #pragma unroll
707	                    for (int off = 16; off > 0; off >>= 1)
708	                        acc += __shfl_down_sync(0xffffffffu, acc, off);
709	                    if (lane == 0) sWpp[c] = acc;     // w[c<k]
710	                }
711	                __syncthreads();
712	                if (warp == 0) {
713	                    for (int a = lane; a < BLK; a += 32) {
714	                        if (a < k) {
715	                            float s = 0.0f;
716	                            for (int c = 0; c < k; ++c)
717	                                s += sT[(long)k * BLK + a] * 0.0f;  // placeholder (overwritten below)
718	                            // T[a,k] = -tau_k * sum_{c<k} T[a,c]*w[c]
719	                            float acc = 0.0f;
720	                            for (int c = 0; c < k; ++c)
721	                                acc += sT[(long)c * BLK + a] * sWpp[c];
722	                            sT[(long)k * BLK + a] = -tau_k * acc;
723	                        } else if (a == k) {
724	                            sT[(long)k * BLK + a] = tau_k;
725	                        }
726	                    }
727	                }
728	                __syncthreads();
729	            } else {
730	                if (warp == 0 && lane == 0) sT[(long)k * BLK + k] = 0.0f;
731	                __syncthreads();
732	            }
733	            // finalize column k diagonal: beta (or alpha if no reflector). tau.
734	            if (tid == 0) {
735	                colk[k] = (tail2 == 0.0f) ? alpha : beta;
736	                taub[j + k] = tau_k;
737	            }
738	            __syncthreads();
739	        }
740	
741	        // ---- write panel (V below diag + R on/above diag) back to H ----
742	        for (long idx = tid; idx < (long)pheight * BLK; idx += nthr) {
743	            int r = idx % pheight;
744	            int c = idx / pheight;
745	            Hb[(long)(j + r) * strideAn + (j + c)] = sP[(long)c * PHpad + r];
746	        }
747	        __syncthreads();
748	
749	        // ---- CONVERT sP in-place to the reflector matrix V (unit lower-trapezoidal):
750	        // V[r,c] = 1 if r==c, sP[r,c] if r>c, 0 if r<c. sP currently holds R above
751	        // the diagonal (and beta on it) -- the WMMA trailing reads sP AS V, so the
752	        // above-diagonal R (and the beta diagonal) MUST be replaced by 0 / 1. sP was
753	        // already written to H, so clobbering it here is safe. Also zero the padded
754	        // rows r in [pheight, PHpad) so the WMMA K-padding contributes 0.
755	        for (long idx = tid; idx < (long)PHpad * BLK; idx += nthr) {
756	            int r = idx % PHpad;
757	            int c = idx / PHpad;
758	            if (r >= pheight) sP[idx] = 0.0f;
759	            else if (r < c)   sP[idx] = 0.0f;
760	            else if (r == c)  sP[idx] = 1.0f;
761	            // r > c (and r < pheight): keep the reflector value already in sP.
762	        }
763	        __syncthreads();
764	
765	        // ---- fused trailing: A[:, j+BLK:N] -= V @ (T^T @ (V^T @ A_strip)) ----
766	        const int ncols = N - (j + BLK);
767	        const int jt = j + BLK;
768	        for (int c0 = 0; c0 < ncols; c0 += BNc) {
769	            // load A strip cols [jt+c0, jt+c0+BNc) into sA (col-major, padded 0).
770	            for (long idx = tid; idx < (long)PHpad * BNc; idx += nthr) {
771	                int r = idx % PHpad;
772	                int c = idx / PHpad;
773	                int gc = c0 + c;             // trailing-relative col
774	                float v = 0.0f;
775	                if (r < pheight && gc < ncols) v = src[(long)(j + r) * strideAn + (jt + gc)];
776	                sA[idx] = v;
777	            }
778	            __syncthreads();
779	
780	            // Step 1: W[BLK x BNc] = V^T @ sA   (M=BLK, N=BNc, K=PHpad). V = sP cols
781	            // as reflectors: V[r,k]=sP[k*PHpad+r] (1 on diag, refl below, 0 above --
782	            // sP holds exactly that after the factor, since rows<k of colk are 0).
783	            // A frag = V^T[k,r] row-major: ldm between rows(k) = PHpad (sP col stride),
784	            //   within row(r) step 1. So frag base sP + mi*16*PHpad (rows=k) won't work
785	            //   directly -- V^T[k,r] = sP[k*PHpad + r]; as a row-major (k,r) matrix the
786	            //   row index k strides by PHpad and col index r strides by 1 -> ldm=PHpad.
787	            {
788	                int mt = BLK / 16, nt = BNc / 16, kt = PHpad / 8;
789	                for (int tile = warp; tile < mt * nt; tile += WB) {
790	                    int mi = tile / nt, ni = tile % nt;
791	                    MFragAcc acc; wmma::fill_fragment(acc, 0.0f);
792	                    for (int kk = 0; kk < kt; ++kk) {
793	                        // V^T rows [mi*16,+16)=k, cols [kk*8,+8)=r -> sP + mi*16*PHpad + kk*8
794	                        MFragAR a; wmma::load_matrix_sync(a, sP + (long)mi * 16 * PHpad + (long)kk * 8, PHpad);
795	                        // sA rows [kk*8,+8)=r, cols [ni*16,+16) -> sA + kk*8 + ni*16*PHpad (col-major ldm PHpad)
796	                        MFragBC b; wmma::load_matrix_sync(b, sA + (long)kk * 8 + (long)ni * 16 * PHpad, PHpad);
797	                        MFragAR ah, al; MFragBC bh, bl;
798	                        #pragma unroll
799	                        for (int e = 0; e < a.num_elements; ++e) { float hv = wmma::__float_to_tf32(a.x[e]); ah.x[e]=hv; al.x[e]=wmma::__float_to_tf32(a.x[e]-hv); }
800	                        #pragma unroll
801	                        for (int e = 0; e < b.num_elements; ++e) { float hv = wmma::__float_to_tf32(b.x[e]); bh.x[e]=hv; bl.x[e]=wmma::__float_to_tf32(b.x[e]-hv); }
802	                        wmma::mma_sync(acc, ah, bh, acc);
803	                        wmma::mma_sync(acc, ah, bl, acc);
804	                        wmma::mma_sync(acc, al, bh, acc);
805	                    }
806	                    wmma::store_matrix_sync(sW + (long)mi * 16 + (long)ni * 16 * BLK, acc, BLK, wmma::mem_col_major);
807	                }
808	            }
809	            __syncthreads();
810	            // Step 2: Wpp[i,g] = -sum_{l<=i} T[l,i] W[l,g]  (T col-major sT[i*BLK+l]).
811	            for (int idx = tid; idx < BLK * BNc; idx += nthr) {
812	                int g = idx / BLK, i = idx % BLK;
813	                float a = 0.f;
814	                for (int l = 0; l <= i; ++l)
815	                    a += sT[(long)i * BLK + l] * sW[(long)l + (long)g * BLK];
816	                sWpp[(long)i + (long)g * BLK] = -a;
817	            }
818	            __syncthreads();
819	            // Step 3: sA += V @ Wpp  (== sA - V @ T^T V^T A). A=V col-major (PHpad x BLK):
820	            // V[r,k]=sP[k*PHpad+r] -> col-major frag ldm between cols(k)=PHpad, within col(r)=1.
821	            {
822	                int mt = PHpad / 16, nt = BNc / 16, kt = BLK / 8;
823	                for (int tile = warp; tile < mt * nt; tile += WB) {
824	                    int mi = tile / nt, ni = tile % nt;
825	                    MFragAcc acc;
826	                    wmma::load_matrix_sync(acc, sA + (long)mi * 16 + (long)ni * 16 * PHpad, PHpad, wmma::mem_col_major);
827	                    for (int kk = 0; kk < kt; ++kk) {
828	                        int kb = kk * 8;
829	                        // V col-major: rows [mi*16,+16)=r, cols [kb,+8)=k -> sP + mi*16 + kb*PHpad
830	                        MFragAC a; wmma::load_matrix_sync(a, sP + (long)mi * 16 + (long)kb * PHpad, PHpad);
831	                        MFragBC b; wmma::load_matrix_sync(b, sWpp + kb + (long)ni * 16 * BLK, BLK);
832	                        MFragAC ah, al; MFragBC bh, bl;
833	                        #pragma unroll
834	                        for (int e = 0; e < a.num_elements; ++e) { float hv = wmma::__float_to_tf32(a.x[e]); ah.x[e]=hv; al.x[e]=wmma::__float_to_tf32(a.x[e]-hv); }
835	                        #pragma unroll
836	                        for (int e = 0; e < b.num_elements; ++e) { float hv = wmma::__float_to_tf32(b.x[e]); bh.x[e]=hv; bl.x[e]=wmma::__float_to_tf32(b.x[e]-hv); }
837	                        wmma::mma_sync(acc, ah, bh, acc);
838	                        wmma::mma_sync(acc, ah, bl, acc);
839	                        wmma::mma_sync(acc, al, bh, acc);
840	                    }
841	                    wmma::store_matrix_sync(sA + (long)mi * 16 + (long)ni * 16 * PHpad, acc, PHpad, wmma::mem_col_major);
842	                }
843	            }
844	            __syncthreads();
845	            // write the updated strip back to H (valid rows/cols only).
846	            for (long idx = tid; idx < (long)pheight * BNc; idx += nthr) {
847	                int r = idx % pheight;
848	                int c = idx / pheight;
849	                int gc = c0 + c;
850	                if (gc < ncols) Hb[(long)(j + r) * strideAn + (jt + gc)] = sA[(long)c * PHpad + r];
851	            }
852	            __syncthreads();
853	        }
854	    }
855	}

