// ===========================================================================
// brief-56 SOLO-PANEL + COOPERATIVE-TRAILING megakernel (variant addressing the
// barrier-count that killed qr_mega_coop_n512). grid=(G, B). Per outer block:
// CTA g==0 factors the WHOLE BLK-wide panel ALONE in smem (intra-CTA __syncthreads
// ONLY -- NO per-column cross-CTA barrier), writes V->Vt + R->H + T->Tbuf + tau;
// then ONE per-matrix barrier; then ALL G CTAs split the trailing col-tiles
// (col_tile % G == g), chunk rows, WMMA. ONE more barrier closes the block. So
// only ~2 cross-CTA barriers/block (32x fewer than the cooperative panel's ~64),
// while still parallelizing the dominant trailing across G CTAs. Cost: g>0 spin
// during g==0's panel, but other matrices fill those SM slots (per-matrix barrier).
// The panel-solo smem (PHpad x BLK = 64KB) caps occupancy but the trailing chunks
// are small; net ~2 blocks/SM at PHpad=512. WMMA tf32x3/fp16x3.
// ---------------------------------------------------------------------------
extern "C" __global__ void qr_mega_solo_n512(
    const float* __restrict__ Ain, float* __restrict__ Hout, float* __restrict__ tauout,
    float* __restrict__ Vtbuf, float* __restrict__ Tbuf,
    int* __restrict__ bar_cnt, int* __restrict__ bar_sense,
    int B, int N, int strideAb, int strideAn,
    int strideVb, int strideVk, int strideVn,
    int strideTb, int strideTk, int strideTn,
    int BLK, int BM, int BNc, int G, int PHpad0, int PREC)
{
    const int g = blockIdx.x; const int bid = blockIdx.y;
    if (bid >= B) return;
    const int tid = threadIdx.x; const int nthr = blockDim.x;
    const int lane = tid & 31; const int warp = tid >> 5; const int WB = nthr >> 5;
    const bool HALF = (PREC >= 1); const bool THREE = (PREC == 3);

    extern __shared__ float smem_sg[];
    // panel-solo (g==0): sPg (PHpad0 x BLK) col-major. sW/sWpp (BLK each). sbc(4).
    float* sPg = smem_sg;
    float* sredw = sPg + (long)PHpad0 * BLK;
    float* sbc = sredw + WB;
    float* sW = sbc + 4;
    float* sWpp = sW + BLK;
    // trailing chunk buffers (all g): sAc(BM*BNc) + sWt(BLK*BNc) + sWtpp(BLK*BNc) + halves
    float* sAc = sWpp + BLK;
    float* sWt = sAc + (long)BM * BNc;
    float* sWtpp = sWt + (long)BLK * BNc;
    __half* sVch = (__half*)(sWtpp + (long)BLK * BNc);
    __half* sVcl = sVch + (long)BLK * BM;
    __half* sAch = sVcl + (long)BLK * BM;
    __half* sAcl = sAch + (long)BM * BNc;
    __half* sWtpph = sAcl + (long)BM * BNc;
    __half* sWtppl = sWtpph + (long)BLK * BNc;

    const float* Ab = Ain + (long)bid * strideAb;
    float* Hb = Hout + (long)bid * strideAb;
    float* taub = tauout + (long)bid * N;
    float* Vb = Vtbuf + (long)bid * strideVb;
    float* Tb = Tbuf + (long)bid * strideTb;
    int* bcnt = bar_cnt + bid; int* bsen = bar_sense + bid;
    int priv_sense = 0;
    #define SOLO_BARRIER() do {                                            \
        __syncthreads();                                                   \
        if (tid == 0) {                                                    \
            __threadfence();                                               \
            int my = priv_sense ^ 1; priv_sense = my;                      \
            if (atomicAdd(bcnt, 1) == G - 1) { atomicExch(bcnt, 0);        \
                asm volatile("st.release.gpu.b32 [%0], %1;" :: "l"(bsen), "r"(my) : "memory"); \
            } else { int seen; do { asm volatile("ld.acquire.gpu.b32 %0, [%1];" : "=r"(seen) : "l"(bsen) : "memory"); } while (seen != my); } \
        }                                                                  \
        __syncthreads();                                                   \
    } while (0)

    const int nblocks = N / BLK;
    for (int jb_i = 0; jb_i < nblocks; ++jb_i) {
        const int j = jb_i * BLK; const int pheight = N - j;
        const int PHpad = ((pheight + 15) / 16) * 16;
        const float* src = (jb_i == 0) ? Ab : Hb;

        // ===== g==0 factors the panel SOLO (intra-CTA only) =====
        if (g == 0) {
            for (long idx = tid; idx < (long)PHpad * BLK; idx += nthr) {
                int r = idx % PHpad; int c = idx / PHpad;
                sPg[idx] = (r < pheight) ? src[(long)(j + r) * strideAn + (j + c)] : 0.0f;
            }
            for (int idx = tid; idx < BLK * BLK; idx += nthr) Tb[idx] = 0.0f;
            __syncthreads();
            for (int k = 0; k < BLK; ++k) {
                float* colk = sPg + (long)k * PHpad;
                float part = 0.0f;
                for (int r = k + 1 + tid; r < pheight; r += nthr) { float x = colk[r]; part += x * x; }
                #pragma unroll
                for (int off = 16; off > 0; off >>= 1) part += __shfl_down_sync(0xffffffffu, part, off);
                if (lane == 0) sredw[warp] = part;
                __syncthreads();
                if (tid == 0) { float s = 0.f; for (int w2 = 0; w2 < WB; ++w2) s += sredw[w2]; sbc[0] = s; sbc[1] = colk[k]; }
                __syncthreads();
                float tail2 = sbc[0], alpha = sbc[1], beta, tau_k, scale;
                if (tail2 == 0.0f) { beta = alpha; tau_k = 0.0f; scale = 1.0f; }
                else { float nx = sqrtf(alpha*alpha+tail2); float sg=(alpha>=0.f)?1.f:-1.f; beta=-sg*nx; tau_k=(beta-alpha)/beta; scale=1.0f/(alpha-beta); }
                for (int r = k + 1 + tid; r < pheight; r += nthr) colk[r] *= scale;
                __syncthreads();
                if (tid == 0) colk[k] = 1.0f;
                __syncthreads();
                if (tau_k != 0.0f) {
                    for (int c = k + 1 + warp; c < BLK; c += WB) {
                        float* colc = sPg + (long)c * PHpad; float acc = 0.0f;
                        for (int r = k + lane; r < pheight; r += 32) acc += colk[r] * colc[r];
                        #pragma unroll
                        for (int off = 16; off > 0; off >>= 1) acc += __shfl_down_sync(0xffffffffu, acc, off);
                        if (lane == 0) sW[c] = tau_k * acc;
                    }
                    __syncthreads();
                    for (int c = k + 1; c < BLK; ++c) {
                        float twc = sW[c]; float* colc = sPg + (long)c * PHpad;
                        for (int r = k + tid; r < pheight; r += nthr) colc[r] -= colk[r] * twc;
                    }
                    __syncthreads();
                    for (int c = warp; c < k; c += WB) {
                        float* colc = sPg + (long)c * PHpad; float acc = 0.0f;
                        for (int r = k + lane; r < pheight; r += 32) acc += colk[r] * colc[r];
                        #pragma unroll
                        for (int off = 16; off > 0; off >>= 1) acc += __shfl_down_sync(0xffffffffu, acc, off);
                        if (lane == 0) sWpp[c] = acc;
                    }
                    __syncthreads();
                    if (warp == 0) for (int a = lane; a < BLK; a += 32) {
                        if (a < k) { float acc = 0.f; for (int c = 0; c < k; ++c) acc += Tb[(long)a*strideTk + (long)c*strideTn] * sWpp[c]; Tb[(long)a*strideTk + (long)k*strideTn] = -tau_k * acc; }
                        else if (a == k) Tb[(long)a*strideTk + (long)k*strideTn] = tau_k;
                    }
                    __syncthreads();
                } else {
                    if (warp == 0 && lane == 0) Tb[(long)k*strideTk + (long)k*strideTn] = 0.0f;
                    __syncthreads();
                }
                if (tid == 0) { colk[k] = (tail2 == 0.0f) ? alpha : beta; taub[j + k] = tau_k; }
                __syncthreads();
            }
            // write panel (R+V) to H and Vt[k,r]
            for (long idx = tid; idx < (long)pheight * BLK; idx += nthr) {
                int r = idx % pheight; int c = idx / pheight;
                Hb[(long)(j + r) * strideAn + (j + c)] = sPg[(long)c * PHpad + r];
            }
            for (long idx = tid; idx < (long)pheight * BLK; idx += nthr) {
                int r = idx % pheight; int c = idx / pheight; float v;
                if (r == c) v = 1.0f; else if (r > c) v = sPg[(long)c * PHpad + r]; else v = 0.0f;
                Vb[(long)c * strideVk + (long)r * strideVn] = v;
            }
        }
        SOLO_BARRIER();   // panel published (by g==0) before the trailing reads it

        // ===== cooperative trailing (col-tile-split across G CTAs) =====
        const int ncols = N - (j + BLK); const int jt = j + BLK;
        int n_ctiles = (ncols + BNc - 1) / BNc;
        for (int ct = g; ct < n_ctiles; ct += G) {
            int c0 = ct * BNc;
            for (int idx = tid; idx < BLK * BNc; idx += nthr) sWt[idx] = 0.0f;
            __syncthreads();
            int nrch = (pheight + BM - 1) / BM;
            for (int ci = 0; ci < nrch; ++ci) {
                int rb = ci * BM;
                for (long idx = tid; idx < (long)BM * BNc; idx += nthr) {
                    int rr = idx % BM; int c = idx / BM; int r = rb + rr; int gc = c0 + c;
                    float v = (r < pheight && gc < ncols) ? src[(long)(j + r) * strideAn + (jt + gc)] : 0.0f;
                    sAc[idx] = v;
                    if (HALF) { __half hi, lo; f2h2(v, hi, lo); sAch[idx]=hi; if (THREE) sAcl[idx]=lo; }
                }
                if (HALF) for (long idx = tid; idx < (long)BLK * BM; idx += nthr) {
                    int k2 = idx / BM; int rr = idx % BM; int r = rb + rr;
                    float v = (r < pheight) ? Vb[(long)k2 * strideVk + (long)r * strideVn] : 0.0f;
                    __half hi, lo; f2h2(v, hi, lo); sVch[(long)k2 * BM + rr]=hi; if (THREE) sVcl[(long)k2 * BM + rr]=lo;
                }
                __syncthreads();
                int mt = BLK/16, nt = BNc/16;
                if (!HALF) {
                    int kt = BM/8;
                    for (int tile = warp; tile < mt*nt; tile += WB) {
                        int mi = tile/nt, ni = tile%nt;
                        MFragAcc acc; wmma::load_matrix_sync(acc, sWt + (long)mi*16 + (long)ni*16*BLK, BLK, wmma::mem_col_major);
                        for (int kk = 0; kk < kt; ++kk) {
                            MFragAR a; wmma::load_matrix_sync(a, Vb + (long)mi*16*strideVk + (long)(rb + kk*8)*strideVn, strideVk);
                            MFragBC b; wmma::load_matrix_sync(b, sAc + (long)kk*8 + (long)ni*16*BM, BM);
                            MFragAR ah, al; MFragBC bh, bl;
                            #pragma unroll
                            for (int e=0;e<a.num_elements;++e){float hv=wmma::__float_to_tf32(a.x[e]);ah.x[e]=hv;al.x[e]=wmma::__float_to_tf32(a.x[e]-hv);}
                            #pragma unroll
                            for (int e=0;e<b.num_elements;++e){float hv=wmma::__float_to_tf32(b.x[e]);bh.x[e]=hv;bl.x[e]=wmma::__float_to_tf32(b.x[e]-hv);}
                            wmma::mma_sync(acc,ah,bh,acc); wmma::mma_sync(acc,ah,bl,acc); wmma::mma_sync(acc,al,bh,acc);
                        }
                        wmma::store_matrix_sync(sWt + (long)mi*16 + (long)ni*16*BLK, acc, BLK, wmma::mem_col_major);
                    }
                } else {
                    int kt = BM/16;
                    for (int tile = warp; tile < mt*nt; tile += WB) {
                        int mi = tile/nt, ni = tile%nt;
                        HFragAcc acc; wmma::load_matrix_sync(acc, sWt + (long)mi*16 + (long)ni*16*BLK, BLK, wmma::mem_col_major);
                        for (int kk = 0; kk < kt; ++kk) {
                            HFragAR vh; wmma::load_matrix_sync(vh, sVch + (long)mi*16*BM + (long)kk*16, BM);
                            HFragBC ah; wmma::load_matrix_sync(ah, sAch + (long)kk*16 + (long)ni*16*BM, BM);
                            wmma::mma_sync(acc, vh, ah, acc);
                            if (THREE) {
                                HFragBC al; wmma::load_matrix_sync(al, sAcl + (long)kk*16 + (long)ni*16*BM, BM); wmma::mma_sync(acc, vh, al, acc);
                                HFragAR vl; wmma::load_matrix_sync(vl, sVcl + (long)mi*16*BM + (long)kk*16, BM); wmma::mma_sync(acc, vl, ah, acc);
                            }
                        }
                        wmma::store_matrix_sync(sWt + (long)mi*16 + (long)ni*16*BLK, acc, BLK, wmma::mem_col_major);
                    }
                }
                __syncthreads();
            }
            for (int idx = tid; idx < BLK * BNc; idx += nthr) {
                int gg = idx / BLK, i = idx % BLK; float a = 0.f;
                for (int l = 0; l <= i; ++l) a += Tb[(long)l*strideTk + (long)i*strideTn] * sWt[(long)l + (long)gg*BLK];
                float wpp = -a; sWtpp[(long)i + (long)gg*BLK] = wpp;
                if (HALF) { __half hi, lo; f2h2(wpp, hi, lo); sWtpph[(long)i + (long)gg*BLK]=hi; if (THREE) sWtppl[(long)i + (long)gg*BLK]=lo; }
            }
            __syncthreads();
            for (int ci = 0; ci < nrch; ++ci) {
                int rb = ci * BM;
                for (long idx = tid; idx < (long)BM * BNc; idx += nthr) {
                    int rr = idx % BM; int c = idx / BM; int r = rb + rr; int gc = c0 + c;
                    sAc[idx] = (r < pheight && gc < ncols) ? src[(long)(j + r) * strideAn + (jt + gc)] : 0.0f;
                }
                if (HALF) for (long idx = tid; idx < (long)BLK * BM; idx += nthr) {
                    int k2 = idx / BM; int rr = idx % BM; int r = rb + rr;
                    float v = (r < pheight) ? Vb[(long)k2 * strideVk + (long)r * strideVn] : 0.0f;
                    __half hi, lo; f2h2(v, hi, lo); sVch[(long)k2 * BM + rr]=hi; if (THREE) sVcl[(long)k2 * BM + rr]=lo;
                }
                __syncthreads();
                int mt = BM/16, nt = BNc/16;
                if (!HALF) {
                    int kt = BLK/8;
                    for (int tile = warp; tile < mt*nt; tile += WB) {
                        int mi = tile/nt, ni = tile%nt;
                        MFragAcc acc; wmma::load_matrix_sync(acc, sAc + (long)mi*16 + (long)ni*16*BM, BM, wmma::mem_col_major);
                        for (int kk = 0; kk < kt; ++kk) {
                            int kb = kk*8;
                            MFragAC a; wmma::load_matrix_sync(a, Vb + (long)(rb + mi*16)*strideVn + (long)kb*strideVk, strideVk);
                            MFragBC b; wmma::load_matrix_sync(b, sWtpp + kb + (long)ni*16*BLK, BLK);
                            MFragAC ah, al; MFragBC bh, bl;
                            #pragma unroll
                            for (int e=0;e<a.num_elements;++e){float hv=wmma::__float_to_tf32(a.x[e]);ah.x[e]=hv;al.x[e]=wmma::__float_to_tf32(a.x[e]-hv);}
                            #pragma unroll
                            for (int e=0;e<b.num_elements;++e){float hv=wmma::__float_to_tf32(b.x[e]);bh.x[e]=hv;bl.x[e]=wmma::__float_to_tf32(b.x[e]-hv);}
                            wmma::mma_sync(acc,ah,bh,acc); wmma::mma_sync(acc,ah,bl,acc); wmma::mma_sync(acc,al,bh,acc);
                        }
                        wmma::store_matrix_sync(sAc + (long)mi*16 + (long)ni*16*BM, acc, BM, wmma::mem_col_major);
                    }
                } else {
                    int kt = BLK/16;
                    for (int tile = warp; tile < mt*nt; tile += WB) {
