  asm volatile("tcgen05.commit.cta_group::1.mbarrier::arrive::one.shared::cluster.b64 [%0];"
               :: "r"(mbar) : "memory");
}
__device__ __forceinline__ void _tc_fence(){ asm volatile("tcgen05.fence::after_thread_sync;"); }

// instruction descriptor for fp16 A/B, fp32 accumulate. M = MMA_M (64 or 128),
// N = MMA_N (mult of 8). a_format=0(f16) b_format=0(f16) c_format=1(f32).
__device__ __forceinline__ uint32_t _idesc_f16(int M, int N){
  return (1U << 4U) | ((uint32_t)N >> 3U << 17U) | ((uint32_t)M >> 4U << 24U);
}
```

Plus two helpers used by both kernels: `_f2h` (`cvt.rn.f16.f32`) and `_elect_one` (`elect.sync`, picks one leader lane).

### B. The production kernel `tc_trailing_wt` — K-tiled, TMEM-accumulating GEMM

Computes `W^T = A_trail^T @ V` (i.e. `W = V^T @ A`), the error-dominant reduction, for one (matrix, NC-column-tile). The MMA tile shapes are **`BM=128` (M-tile), `NN=32` (N=BLK), K-atom=16**, K-tiled with `BK` (tested `BK=64`).

```cuda
extern "C" __global__ void tc_trailing_wt(
    const float* A, const float* Vt, float* WT,
    int B, int NC, int P, int BK,
    long sab, long san,          // A strides (matrix, row)  [A is the trailing block base]
    long svb, long svk, long svn,// Vbuf strides (matrix, refl-idx, row)
    long swb, long swc           // WT strides (matrix, col)  [WT row-stride = BLK=32]
){
  const int BM = 128, NN = 32;   // M-tile=128, N=BLK=32
  const int tid = threadIdx.x, wid = tid >> 5, lane = tid & 31;
  const int mt = blockIdx.x;     // M-tile over NC
  const int bid = blockIdx.y;    // matrix
  if (bid >= B) return;
  const int row0 = mt * BM;
  const float* Ab = A + (long)bid * sab;        // trailing block base for this matrix
  const float* Vb = Vt + (long)bid * svb;       // Vbuf[bid] (V^T, BLK x P)
  float* WTb = WT + (long)bid * swb;
  extern __shared__ __align__(1024) char tcw_smem[];
  ushort* As = reinterpret_cast<ushort*>(tcw_smem);
  const int Asz = BM * BK;
  ushort* Bs = As + Asz;
  const int A_smem = (int)__cvta_generic_to_shared(tcw_smem);
  const int B_smem = A_smem + Asz * (int)sizeof(ushort);
  #pragma nv_diag_suppress static_var_with_dynamic_init
  __shared__ uint64_t tcw_mbar[1];
  __shared__ int tcw_tmem[1];
  const int mbar_addr = (int)__cvta_generic_to_shared(tcw_mbar);
  if (wid == 0 && _elect_one()) _mbar_init(mbar_addr, 1);
  else if (wid == 1){ int a = (int)__cvta_generic_to_shared(tcw_tmem); _tc_alloc(a, NN); }
  __syncthreads();
  const int taddr = tcw_tmem[0];
  const uint32_t idesc = _idesc_f16(BM, NN);
  const int rmax = min(BM, NC - row0);
  const int nkt = (P + BK - 1) / BK;
  for (int kt = 0; kt < nkt; kt++){
    const int k0 = kt * BK;
    const int kthis = min(BK, P - k0);
    for (int i = tid; i < BM * BK; i += blockDim.x) As[i] = 0;
    for (int i = tid; i < NN * BK; i += blockDim.x) Bs[i] = 0;
    __syncthreads();
    // Aop = A_trail^T tile: element (c-row, k) = A[row=k0+k, col=row0+c]
    for (int i = tid; i < rmax * kthis; i += blockDim.x){
      int c = i / kthis, k = i % kthis, b = k >> 3, kk = k & 7;
      As[b * (BM * 8) + c * 8 + kk] = _f2h(Ab[(long)(k0 + k) * san + (long)(row0 + c)]);
    }
    // Bop = Vbuf tile: element (refl i2, k) = Vbuf[i2, k0+k]
    for (int i = tid; i < NN * kthis; i += blockDim.x){
      int i2 = i / kthis, k = i % kthis, b = k >> 3, kk = k & 7;
      Bs[b * (NN * 8) + i2 * 8 + kk] = _f2h(Vb[(long)i2 * svk + (long)(k0 + k) * svn]);
    }
    __syncthreads();
    if (wid == 0 && _elect_one()){
      _tc_fence();
      int na = BK / 16;
      for (int ka = 0; ka < na; ka++){
        uint64_t ad = _smem_desc(A_smem + ka * BM * 32, BM);
        uint64_t bd = _smem_desc(B_smem + ka * NN * 32, NN);
        _tc_mma_f16(taddr, ad, bd, idesc, (kt > 0) || (ka > 0));
      }
      _tc_commit(mbar_addr);
    }
    _mbar_wait(mbar_addr, kt & 1);
    __syncthreads();  // smem reuse before next K-tile
  }
  _tc_fence();
  // read W^T (NC-tile rows x BLK=32). warp wid owns rows wid*32 of this tile.
  for (int n = 0; n < NN / 8; n++){
    float t[8];
    const int addr = taddr + ((wid * 32) << 16) + (n * 8);
    asm volatile("tcgen05.ld.sync.aligned.32x32b.x8.b32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
                : "=f"(t[0]),"=f"(t[1]),"=f"(t[2]),"=f"(t[3]),
                  "=f"(t[4]),"=f"(t[5]),"=f"(t[6]),"=f"(t[7]) : "r"(addr));
    asm volatile("tcgen05.wait::ld.sync.aligned;");
    int r = wid * 32 + lane;
    if (r < rmax){
      #pragma unroll
      for (int i = 0; i < 8; i++) WTb[(long)(row0 + r) * swc + n * 8 + i] = t[i];
    }
  }
  __syncthreads();
  if (wid == 0 && _elect_one()) _tc_dealloc(taddr, NN);
}
```

**Mechanics that are load-bearing:**
- **TMEM alloc:** warp 1's leader lane calls `_tc_alloc(smem_slot_addr, NN=32)`; the resulting TMEM base column-address is written by hardware into `tcw_tmem[0]` (shared int), read back by all threads as `taddr` after `__syncthreads()`.
- **K-tiling loop:** outer over `nkt = ceil(P/BK)` K-tiles; inner over `na = BK/16` MMA atoms (K=16 each). The smem descriptor advances `A_smem + ka*BM*32` and `B_smem + ka*NN*32` (32 = 16 K-elems × 2 bytes) for each atom.
- **Accumulation predicate:** `enable_d = (kt>0)||(ka>0)` — first atom of first K-tile writes (clears) TMEM, all later atoms accumulate. The accumulator never leaves TMEM until the final `tcgen05.ld`.
- **Smem layout for descriptors:** K-major "blocks of (height,8)" — for A, `As[b*(BM*8) + c*8 + kk]` where `b = k>>3, kk = k&7`; for B, `Bs[b*(NN*8) + i2*8 + kk]`. Inputs are cast fp32→fp16 on store via `_f2h`.
- **Result read:** `tcgen05.ld.sync.aligned.32x32b.x8.b32` reads 8 fp32 columns per call; warp `wid` owns TMEM rows `wid*32` (lane-row), address = `taddr + ((wid*32)<<16) + n*8`. Block = 128 threads = 4 warps → covers 128 M-rows.

